package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.ErrorSampleRateVO;

class ErrorSampleRateValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of error sample rate of observed source")
  void test_error_sample_rate_value_holder_assign_plain_value() {
    Object holder = new Object();
    ErrorSampleRateValueHolder<Object> value = new ErrorSampleRateValueHolder<>(holder);
    Assertions.assertSame(holder, value.errorSampleRate(1), "Setters must return the holder");
    Assertions.assertTrue(value.getErrorSampleRateValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getErrorSampleRate().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.errorSampleRateNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getErrorSampleRateValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getErrorSampleRate().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of error sample rate of observed source")
  void test_error_sample_rate_value_holder_assign_value_object() {
    Object holder = new Object();
    ErrorSampleRateValueHolder<Object> value = new ErrorSampleRateValueHolder<>(holder);
    ErrorSampleRateVO vo = ErrorSampleRateVO.from(1);
    Assertions.assertFalse(value.getErrorSampleRateValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.errorSampleRate(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getErrorSampleRateValue().orElseThrow());
    Assertions.assertSame(holder, value.errorSampleRate(Optional.empty()));
    Assertions.assertFalse(value.getErrorSampleRateValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.errorSampleRate(Optional.of(vo)));
    Assertions.assertSame(vo, value.getErrorSampleRateValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of error sample rate of observed source against the original")
  void test_error_sample_rate_value_holder_read() {
    Object holder = new Object();
    ErrorSampleRateValueHolder<Object> value = new ErrorSampleRateValueHolder<>(holder);
    ErrorSampleRateVO vo = ErrorSampleRateVO.from(1);
    ErrorSampleRateVO other = ErrorSampleRateVO.from(1);
    ObservedSource original = Mockito.mock(ObservedSource.class);
    Mockito.when(original.getErrorSampleRateValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readErrorSampleRate(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readErrorSampleRate(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.errorSampleRate(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readErrorSampleRate(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readErrorSampleRate(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of error sample rate of observed source")
  void test_error_sample_rate_value_holder_unset() {
    Object holder = new Object();
    ErrorSampleRateValueHolder<Object> value = new ErrorSampleRateValueHolder<>(holder);
    ErrorSampleRateVO vo = ErrorSampleRateVO.from(1);
    value.errorSampleRate(vo);
    Assertions.assertSame(holder, value.unsetErrorSampleRateIfMatches("errorSampleRate_other"));
    Assertions.assertTrue(value.getErrorSampleRateValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetErrorSampleRateIfMatches("errorSampleRate"));
    Assertions.assertFalse(value.getErrorSampleRateValue().isPresent(),
        "The field name must clear the value");
    value.errorSampleRate(vo);
    Assertions.assertSame(holder, value.unsetErrorSampleRate());
    Assertions.assertFalse(value.getErrorSampleRateValue().isPresent(),
        "Unset must clear the value");
  }
}
